local config = {
  ui_story_5065_50650101_1_dialog_content = "Good morning, instructor!",
  ui_story_5065_50650101_2_dialog_content = "Good morning. Are you Paloma, the trainee recommended by Dawn Academy?",
  ui_story_5065_50650101_3_dialog_content = "Yes, but people usually just call me Pam. I'm grateful to the Academy and to the Lumopolis Temple for this precious training opportunity!",
  ui_story_5065_50650101_4_dialog_content = "Pam, do you know what the Lumopolis Temple is all about?",
  ui_story_5065_50650101_5_dialog_content = "(Testing me on my knowledge already...?)",
  ui_story_5065_50650101_6_dialog_content = "(Good thing I memorized everything I could learn about the Lumopolis Temple a long time ago!)",
  ui_story_5065_50650101_7_dialog_content = "Ahem... the Lumopolis Temple is the most holy and sacred place in all of Lumopolis!",
  ui_story_5065_50650101_8_dialog_content = "The temple carries our devotion to the God of Light to the heavens above, and blesses the people below with wisdom and enlightenment.",
  ui_story_5065_50650101_9_dialog_content = "The temple not only oversees every church in Lumopolis, it also houses three sacred relics: a blade, a tome, and a staff!",
  ui_story_5065_50650101_10_dialog_content = "These three relics represent the Lumo Knights, the Dawn Academy, and the Hall of Justice respectively.",
  ui_story_5065_50650101_11_dialog_content = "No wonder you're the Dawn Academy's recommendation; you've definitely done your homework.",
  ui_story_5065_50650101_12_dialog_content = "Theoretical knowledge is all well and good, but without practical experience, it's just a pie in the sky. Up next, I'll have you engage in affairs of various temple affiliations.",
  ui_story_5065_50650101_13_dialog_content = "You'll need to quickly learn how to handle a variety of tasks within a limited time frame, gaining a full understanding of the temple's significance to Lumopolis.",
  ui_story_5065_50650101_14_dialog_content = "You might face challenges and even setbacks, but it's okay; you can choose to quit anytime.",
  ui_story_5065_50650101_15_dialog_content = "I... I'll never quit!",
  ui_story_5065_50650101_16_dialog_content = "Good, I hope your actions live up to your resolve.",
  ui_story_5065_50650101_17_dialog_content = "It just so happens that the Hall of Justice could use some extra help lately. Why don't you start by pitching in there?",
  ui_story_5065_50650101_18_dialog_content = "Once you're at the Hall of Justice, find the Junior Judge. He'll clue you in on what's up next.",
  ui_story_5065_50650101_19_dialog_content = "White Night up high! May the God of Light bring you good luck.",
  ui_story_5065_50650102_1_dialog_content = "Ugh, how come she's still not here? I'm gonna charge her with the latecomer crime and give her the harshest punishment!",
  ui_story_5065_50650102_2_dialog_content = "Is it really a crime to be late in Lumopolis...?",
  ui_story_5065_50650102_3_dialog_content = "Look, I'm a judge, so if I say it's a crime, it's a crime. You have no right to question it.",
  ui_story_5065_50650102_4_dialog_content = "U-Understood! I didn't mean to refute you, so please forgive me!",
  ui_story_5065_50650102_5_dialog_content = "Since you are a judge... Then surely you must know the Junior Judge as well?",
  ui_story_5065_50650102_6_dialog_content = "Ahem, are you a fan of his?",
  ui_story_5065_50650102_7_dialog_content = "Er... In a way, yes. To work in the Hall of Justice and pass the God of Light's judgment is one of the greatest honors a person can attain.",
  ui_story_5065_50650102_8_dialog_content = "Although many people say that the Junior Judge is too low-ranking and irritable, I strongly believe...",
  ui_story_5065_50650102_9_dialog_content = "Wh-What?! Did you say I have a low rank and a bad temper? How dare you!",
  ui_story_5065_50650102_10_dialog_content = "Um, you wouldn't happen to be the Junior Judge, would you? Please let me explain, as I didn't finish my sentence...",
  ui_story_5065_50650102_11_dialog_content = "I strongly believe that anyone who works for the Hall of Justice must be a genius worthy of respect! That's why I trust and respect you so much!",
  ui_story_5065_50650102_12_dialog_content = "Huh, you catch on quick. You're recommended here by the Lumopolis Temple, right? Hand it over.",
  ui_story_5065_50650102_13_dialog_content = "Hand what over...?",
  ui_story_5065_50650102_14_dialog_content = "The gift for your \"Mentor in the Hall of Justice.\" You didn't forget to prepare one, did you?",
  ui_story_5065_50650102_15_dialog_content = "I-I had no idea I was supposed to prepare a gift for you...",
  ui_story_5065_50650102_16_dialog_content = "Heavens, why do the students recommended by Dawn Academy get worse every year?",
  ui_story_5065_50650102_17_dialog_content = "Well, forget it. Let's just cut to the chase.",
  ui_story_5065_50650102_18_dialog_content = "I've got a case recently, ahem... the kind the Chief Judge really values.",
  ui_story_5065_50650102_19_dialog_content = "There's a gang of troublemakers from Lower Lumopolis, stealing valuables from many noble households, and they're still hiding in Lumopolis!",
  ui_story_5065_50650102_20_dialog_content = "Unfortunately, I haven't been able to nab them, so this case is still sitting on my desk, seriously affecting my performance rating...",
  ui_story_5065_50650102_21_dialog_content = "Ahem, don't get me wrong; catching them isn't hard. I just wanted to leave the case for a newbie like you as an opportunity.",
  ui_story_5065_50650102_22_dialog_content = "Now, I officially hand over the case to you. You can help me catch those despicable thieves, right?",
  ui_story_5065_50650102_23_dialog_content = "Y-You're trusting me with this? But I only just became a trainee! I have no idea how to handle this...",
  ui_story_5065_50650102_24_dialog_content = "This place is not a school, where teachers always give you time to review, prepare, and even provide last-minute highlights before exams.",
  ui_story_5065_50650102_25_dialog_content = "This is how work is; everyone grows through hands-on experience, got it?",
  ui_story_5065_50650102_26_dialog_content = "I see. Very well, I understand! It seems I still have much to learn from you, sir.",
  ui_story_5065_50650102_27_dialog_content = "Hmm, very good. Word is that these thieves will be in disguise near the Shuttle Hub in Lumopolis Gardens today.",
  ui_story_5065_50650102_28_dialog_content = "Whatever you do, don't let them get away! Eh... what's your name again?",
  ui_story_5065_50650102_29_dialog_content = "Paloma!",
  ui_story_5065_50650102_30_dialog_content = "Paloma, time to move! Next time we meet, I hope to see you bringing in the thieves you've caught.",
  ui_story_5065_50650103_1_dialog_content = "Greetings! Pardon me, but have you seen any suspicious people today?",
  ui_story_5065_50650103_2_dialog_content = "S-Suspicious people? I don't think there's any...",
  ui_story_5065_50650103_3_dialog_content = "Sorry, I'm in a hurry. The airship is about to take off. Maybe you should ask someone else.",
  ui_story_5065_50650103_4_dialog_content = "(That's strange, it shouldn't be time for the guards to change shifts, so why is this guard doing as he pleases?)",
  ui_story_5065_50650103_5_dialog_content = "(Don't tell me...?!)",
  ui_story_5065_50650103_6_dialog_content = "Just a moment, sir!",
  ui_story_5065_50650103_7_dialog_content = "...!!!",
  ui_story_5065_50650103_8_dialog_content = "(He ran off... Could he have been one of those thieves in disguise?)",
  ui_story_5065_50650103_9_dialog_content = "Halt!",
  ui_story_5065_50650104_1_dialog_content = "Huh? You're back already?",
  ui_story_5065_50650104_2_dialog_content = "Your Honor, I captured one of the suspects! He was impersonating a Lumo Guard and nearly escaped on an airship!",
  ui_story_5065_50650104_3_dialog_content = "You? Caught them? The fugitive? This is... unbelievable...",
  ui_story_5065_50650104_4_dialog_content = "Oh no, what I meant was, don't you think this quest is quite simple?",
  ui_story_5065_50650104_5_dialog_content = "Let go of me! Do you have any evidence?!",
  ui_story_5065_50650104_6_dialog_content = "Evidence? Isn't that something you can plant as much as you want?",
  ui_story_5065_50650104_7_dialog_content = "What do you mean by that, sir...?",
  ui_story_5065_50650104_8_dialog_content = "Ahem, I mean, I'll interrogate this thief thoroughly, making them confess and face the consequences.",
  ui_story_5065_50650104_9_dialog_content = "Paloma, just watch and learn.",
  ui_story_5065_50650104_10_dialog_content = "But...",
  ui_story_5065_50650104_11_dialog_content = "But what? Don't think that catching a thief gives you the right to make impudent requests in front of me.",
  ui_story_5065_50650104_12_dialog_content = "But the thief broke out of your handcuffs and escaped!",
  ui_story_5065_50650104_13_dialog_content = "Go after him! Now!",
  ui_story_5065_50650104_14_dialog_content = "This is outrageous!",
  ui_story_5065_50650104_15_dialog_content = "Sir, I managed to apprehend the thief yet again, so please don't be upset! Should we use more than one pair of handcuffs on him?",
  ui_story_5065_50650104_16_dialog_content = "Hmph, no need. I'll lock him up in the prison directly!",
  ui_story_5065_50650104_17_dialog_content = "You did pretty well today, not a letdown. But I'll take it from here.; you don't need to worry about it.",
  ui_story_5065_50650201_1_dialog_content = "Sigh... This is not good...",
  ui_story_5065_50650201_2_dialog_content = "What happened, Your Honor? Is there anything I can do to help?",
  ui_story_5065_50650201_3_dialog_content = "Ah, you showed up right on time! It's my turn today to open the office door before everyone else gets here.",
  ui_story_5065_50650201_4_dialog_content = "But the office key got swallowed by the fish in the pond!",
  ui_story_5065_50650201_5_dialog_content = "A fish swallowed the key? I hope it's okay...",
  ui_story_5065_50650201_6_dialog_content = "There are so many fish and I can't tell which one... Wait, shouldn't you be more concerned about me?",
  ui_story_5065_50650201_7_dialog_content = "I-I mean, are you okay sir?",
  ui_story_5065_50650201_8_dialog_content = "Do I look like I'm okay? I have to open the office before everyone else arrives, or my performance rating for this month will... Ahem... Anyway, I happen to have a task for you.",
  ui_story_5065_50650201_9_dialog_content = "Dawn Academy, Lumopolis Courtyard, and Lower Lumopolis each have a scale sculpture. They look just like the one in front of the Hall of Justice.",
  ui_story_5065_50650201_10_dialog_content = "Psst! Keep this between us... If you finish the quest of the scale, it'll drop a Golden Weight.",
  ui_story_5065_50650201_11_dialog_content = "As long as you collect the golden weights from the three different scale sculptures, you can combine them at the scale in front of the Hall of Justice to make a key!",
  ui_story_5065_50650201_12_dialog_content = "Your task is to go and help me collect these three golden weights.",
  ui_story_5065_50650201_13_dialog_content = "You're not coming with me, sir?",
  ui_story_5065_50650201_14_dialog_content = "Well, I have other things to attend to... You know, in case someone shows up, I'll have to find an excuse to send them away.",
  ui_story_5065_50650201_15_dialog_content = "Get moving! Hurry!",
  ui_story_5065_50650202_1_dialog_content = "A golden weight really did come out!",
  ui_story_5065_50650202_2_dialog_content = "Thanks to the knowledge accumulated over the days, these quests aren't difficult at all.",
  ui_story_5065_50650202_3_dialog_content = "At this rate, I should make in time... I need to hurry to the next set of scales!",
  ui_story_5065_50650203_1_dialog_content = "That's another golden weight!",
  ui_story_5065_50650203_2_dialog_content = "This is great, now I just need one more and the set is complete.",
  ui_story_5065_50650204_1_dialog_content = "I finally collected all three golden weights!",
  ui_story_5065_50650204_2_dialog_content = "Can I make it in time? I should hurry back and give these to the Junior Judge...",
  ui_story_5065_50650205_1_dialog_content = "*snoring*",
  ui_story_5065_50650205_2_dialog_content = "I'm not too late, am I, sir?",
  ui_story_5065_50650205_3_dialog_content = "Huh?! The office key was taken by that trainee called Paloma!",
  ui_story_5065_50650205_4_dialog_content = "Er, I'm sorry if I woke you up, sir, but I never took the key...",
  ui_story_5065_50650205_5_dialog_content = "Ahem, it's you, huh? Thought it was one of my colleagues. Have you finished the task I gave you?",
  ui_story_5065_50650205_6_dialog_content = "If you fail to bring back three golden weights, I won't be able to obtain the key. So it wouldn't be an exaggeration to say you've taken the key away, right?",
  ui_story_5065_50650205_7_dialog_content = "I've brought back all three of the golden weights you requested.",
  ui_story_5065_50650205_8_dialog_content = "You... you mean you actually completed those quests?",
  ui_story_5065_50650205_9_dialog_content = "Did the trainee just complete the quests that even I couldn't handle?",
  ui_story_5065_50650205_10_dialog_content = "I mean... there's no denying my judgment of people seems spot on!",
  ui_story_5065_50650205_11_dialog_content = "Don't worry. I'll put in a good word for you with your mentor.",
  ui_story_5065_50650205_12_dialog_content = "Thank you for your support, Junior Judge!",
  ui_story_5065_50650301_1_dialog_content = "Good morning, Your Honor!",
  ui_story_5065_50650301_2_dialog_content = "Well, Pam, I've been waiting for you.",
  ui_story_5065_50650301_3_dialog_content = "I-I'm sorry... Am I late again?",
  ui_story_5065_50650301_4_dialog_content = "You did miss the thrilling moment of my interrogation with the thief, but it's okay. Just know that...",
  ui_story_5065_50650301_5_dialog_content = "... after my brilliant interrogation, the thief we caught a few days ago finally spilled the beans about his accomplices' whereabouts!",
  ui_story_5065_50650301_6_dialog_content = "White Night up high! How did you do that?! He hasn't given us a single clue for the last few days!",
  ui_story_5065_50650301_7_dialog_content = "Hmph, if you want to know, I can teach you later.",
  ui_story_5065_50650301_8_dialog_content = "Right now, we need to capitalize on our advantage and round up the rest of the thieves!",
  ui_story_5065_50650301_9_dialog_content = "Those wretched criminals will be waiting for a meet-up near the scale sculpture in Lumopolis Courtyard today. Hurry and apprehend them!",
  ui_story_5065_50650301_10_dialog_content = "As you command, Your Honor!",
  ui_story_5065_50650302_1_dialog_content = "Wearing the same disguises again, eh?",
  ui_story_5065_50650302_2_dialog_content = "Who are you?! How dare you be disrespectful to the guards of Lumopolis?",
  ui_story_5065_50650302_3_dialog_content = "I... I won't let you sully the name of our city's guards any longer!",
  ui_story_5065_50650303_1_dialog_content = "Your Honor, I brought back the thief's accomplice!",
  ui_story_5065_50650303_2_dialog_content = "How come there's only one of them?!",
  ui_story_5065_50650303_3_dialog_content = "W-Well I only noticed one suspicious person in Lumopolis Courtyard.",
  ui_story_5065_50650303_4_dialog_content = "Why did you only check Lumopolis Courtyard? Starting to slack off already, huh?",
  ui_story_5065_50650303_5_dialog_content = "Didn't I mention there was another accomplice hiding in the Lower Lumopolis?",
  ui_story_5065_50650303_6_dialog_content = "D-Did you say that, sir?",
  ui_story_5065_50650303_7_dialog_content = "Wow, at the first sign of trouble, you're already trying to shift blame to your superior? Why not consider if you remembered wrong?",
  ui_story_5065_50650303_8_dialog_content = "So young, yet already picking up these bad practices. Who knows what will become of you in the future?",
  ui_story_5065_50650303_9_dialog_content = "I'm sorry. It's possible that I'm truly not remembering things correctly...",
  ui_story_5065_50650303_10_dialog_content = "But don't worry sir, I'll head down to Lower Lumopolis and apprehend the remaining criminals at once!",
  ui_story_5065_50650304_1_dialog_content = "Another lone guard looking around suspiciously...",
  ui_story_5065_50650304_2_dialog_content = "He may be disguised as a Lumopolis guard, but there's no hiding his criminal intent.",
  ui_story_5065_50650304_3_dialog_content = "Wh-What are you doing?!",
  ui_story_5065_50650304_4_dialog_content = "Taking you where you belong.",
  ui_story_5065_50650305_1_dialog_content = "Hmmm, that's about right.",
  ui_story_5065_50650305_2_dialog_content = "Given that you've rounded up all the thief's accomplices, I can let this unpleasant incident pass today.",
  ui_story_5065_50650305_3_dialog_content = "Thank you for being so understanding, Your Honor!",
  ui_story_5065_50650305_4_dialog_content = "Is there anything else I can do to help you?",
  ui_story_5065_50650305_5_dialog_content = "The upcoming trials are quite different from capturing criminals; they demand greater intelligence and skill.",
  ui_story_5065_50650305_6_dialog_content = "Even if I tell you the tricks, you won't grasp them in a short time. Besides, a trainee doesn't need to get into those overly intricate matters.",
  ui_story_5065_50650305_7_dialog_content = "I-Is that so...? But sir, if you just give me a chance, I promise I won't disappoint you!",
  ui_story_5065_50650305_8_dialog_content = "That's enough for today. Aren't you tired yet? Head back, and I'll take care of the rest!",
  ui_story_5065_50650305_9_dialog_content = "Huh? Are you showing me your consideration by sending me home to rest?",
  ui_story_5065_50650305_10_dialog_content = "Huh? Uh, ahem... Yes, that's exactly what I meant.",
  ui_story_5065_50650305_11_dialog_content = "Thank you so much, sir!",
  ui_story_5065_50650305_12_dialog_content = "You were right. Paloma's dream has become entangled with my own...",
  ui_story_5065_50650305_13_dialog_content = "To be more precise, the person staying here who refuses to wake up is the Pam you met in your dream.",
  ui_story_5065_50650305_14_dialog_content = "Pam... She's dreaming of the time when she first became a trainee?",
  ui_story_5065_50650305_15_dialog_content = "This was the happiest time in her life.",
  ui_story_5065_50650305_16_dialog_content = "Do I have to tell Pam the truth? I can't bear to ruin her happiness...",
  ui_story_5065_50650305_17_dialog_content = "But if she doesn't wake up, you won't have a way to wake up either.",
  ui_story_5065_50650305_18_dialog_content = "Pam, you were the one who helped me realize that this dream was nothing but an illusion. In the end, we all need to wake up and face our true selves.",
  ui_story_5065_50650305_19_dialog_content = "This time, it's my turn to wake you up.",
  ui_story_5065_50650401_1_dialog_content = "Good morning, Your Honor!",
  ui_story_5065_50650401_2_dialog_content = "Oh, Pam, you're right on time.",
  ui_story_5065_50650401_3_dialog_content = "I just realized that I have some books borrowed from Dawn Academy here, and they're nearing their due date.",
  ui_story_5065_50650401_4_dialog_content = "Help me return them, and then borrow a few of the same books.",
  ui_story_5065_50650401_5_dialog_content = "Are you saying... You want to continue borrowing these books?",
  ui_story_5065_50650401_6_dialog_content = "No, I've already renewed these books ten times, and I can't renew them anymore.",
  ui_story_5065_50650401_7_dialog_content = "Good thing Dawn Academy keeps a bunch of the same books. Just fetch some different copies for me.",
  ui_story_5065_50650401_8_dialog_content = "I see... I wonder what kinds of books warrant ten renewals in a row?",
  ui_story_5065_50650401_9_dialog_content = "\"The Spirit of Legal Debate,\" \"Conspectus of Law\"... These books look so esoteric! What exactly do they discuss?",
  ui_story_5065_50650401_10_dialog_content = "Well, um... if you want to know, I could write you a summary, but it might take some time.",
  ui_story_5065_50650401_11_dialog_content = "Just go get them for me now.",
  ui_story_5065_50650401_12_dialog_content = "Very well, leave it to me!",
  ui_story_5065_50650402_1_dialog_content = "These books are much heavier than they look...",
  ui_story_5065_50650402_2_dialog_content = "Phew! Thank goodness I'm almost at the library! Just a little further now!",
  ui_story_5065_50650402_3_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5065_50650402_4_dialog_content = "Oh no... I'm so sorry!",
  ui_story_5065_50650402_5_dialog_content = "I was running so quickly that I didn't notice you there... Are you alright?",
  ui_story_5065_50650402_6_dialog_content = "(Those were my words when Pam and I first met. I wonder if she still remembers.)",
  ui_story_5065_50650402_7_dialog_content = "Oh...",
  ui_story_5065_50650402_8_dialog_content = "I-I'm fine. Please don't blame yourself, lady knight.",
  ui_story_5065_50650402_9_dialog_content = "(Pam said the exact same thing back then too!)",
  ui_story_5065_50650402_10_dialog_content = "I was in a hurry as well, and I failed to notice my surroundings...",
  ui_story_5065_50650402_11_dialog_content = "If anything, I should be the one apologizing!",
  ui_story_5065_50650402_12_dialog_content = "(The way she's looking at me... It's as if she's looking at a complete stranger.)",
  ui_story_5065_50650402_13_dialog_content = "Do you really not remember who I am?",
  ui_story_5065_50650402_14_dialog_content = "Er... Judging from your attire, may I assume you are a Justice Knight?",
  ui_story_5065_50650402_15_dialog_content = "Something about you is somewhat familiar, yes. Have we seen each other in the Hall of Justice before?",
  ui_story_5065_50650402_16_dialog_content = "I'm Irridon, the person you wish to exact revenge upon... Don't you remember any of this?",
  ui_story_5065_50650402_17_dialog_content = "From a young age, I have always embraced the God of Light's teachings. I would never seek vengeance against others easily...",
  ui_story_5065_50650402_18_dialog_content = "Stop indulging in this fantasy already! It's all a lie, now wake up!!",
  ui_story_5065_50650402_19_dialog_content = "Are... Are you sure you're not mistaking me for someone else?",
  ui_story_5065_50650402_20_dialog_content = "Forgive me, but I'm on an important errand. I can't stay here any longer, but I pray that you find the person you're looking for.",
  ui_story_5065_50650403_1_dialog_content = "No, I should be the one apologizing. I knocked your books out of your hands, so at least let me help you pick them up.",
  ui_story_5065_50650403_2_dialog_content = "It's alright, I can gather them myself quickly enough!",
  ui_story_5065_50650403_3_dialog_content = "Whoever you're looking for must be very important to you, yes? Please don't delay your search for my sake.",
  ui_story_5065_50650403_4_dialog_content = "...",
  ui_story_5065_50650404_1_dialog_content = "Sigh, who left all of these paper scraps strewn across the campus courtyard? If no one is going to clean it up, then I guess it falls to me...",
  ui_story_5065_50650404_2_dialog_content = "Pam...",
  ui_story_5065_50650404_3_dialog_content = "Lady Irridon?",
  ui_story_5065_50650404_4_dialog_content = "You finally remember me?!",
  ui_story_5065_50650404_5_dialog_content = "... You just introduced yourself to me a few minutes ago.",
  ui_story_5065_50650404_6_dialog_content = "A Justice Knight's work must take up most of their day, isn't it? Why have you been following me all this time?",
  ui_story_5065_50650404_7_dialog_content = "I... I still haven't properly apologized for running into you earlier.",
  ui_story_5065_50650404_8_dialog_content = "I would like to help you... If not by cleaning up this mess, then by returning your books for you. Is that alright?",
  ui_story_5065_50650404_9_dialog_content = "I couldn't possibly trouble you with something as menial as cleaning, but if you insist on helping me...",
  ui_story_5065_50650404_10_dialog_content = "Could I ask you to return these books, then check out a different copy for each one again?",
  ui_story_5065_50650404_11_dialog_content = "Yes, of course!",
  ui_story_5065_50650405_1_dialog_content = "Here are the books you requested, Pam.",
  ui_story_5065_50650405_2_dialog_content = "Thank you, Lady Irridon!",
  ui_story_5065_50650405_3_dialog_content = "Hmm? \"Dreams and Reality,\" \"The Awakening,\" \"How to Avoid Falling Victim to Your Dreams\"...?",
  ui_story_5065_50650405_4_dialog_content = "These are clearly not the books I asked for!",
  ui_story_5065_50650405_5_dialog_content = "Pam, please! The world around us isn't the real world, it's just a dream! Your dream!",
  ui_story_5065_50650405_6_dialog_content = "If we remain trapped in here... Our real selves will gradually lose their minds until we die altogether!",
  ui_story_5065_50650405_7_dialog_content = "Please stop lying to yourself! Open your eyes and see this world for what it truly is!",
  ui_story_5065_50650405_8_dialog_content = "What exactly do you want from me? Ever since we stumbled into each other, you've done nothing but say the strangest things.",
  ui_story_5065_50650405_9_dialog_content = "I don't understand your words, nor do I want to...",
  ui_story_5065_50650405_10_dialog_content = "Now if you'll excuse me, I have urgent matters to attend to. Matters which are very important to me, as well.",
  ui_story_5065_50650405_11_dialog_content = "In the name of the God of Light, I ask that you trouble me no further. White Night up high, and good day to you.",
  ui_story_5065_50650405_12_dialog_content = "But these tasks are completely meaningless to you, Pam!",
  ui_story_5065_50650405_13_dialog_content = "Lady Irridon, I can tell just from looking that you hail from a noble household, so you may not understand...",
  ui_story_5065_50650405_14_dialog_content = "But becoming an initiate has been a very difficult ordeal for me. If I wish to realize my dreams, I must complete these tasks flawlessly and to the best of my abilities.",
  ui_story_5065_50650405_15_dialog_content = "How could you possibly claim that these mean nothing to me?",
  ui_story_5065_50650405_16_dialog_content = "If you truly intend to stop me... Th-Then I have no choice but to be more assertive!",
  ui_story_5065_50650406_1_dialog_content = "Forgive me, Your Honor... I encountered a few obstacles while carrying out my tasks.",
  ui_story_5065_50650406_2_dialog_content = "I could have returned with your books sooner.",
  ui_story_5065_50650406_3_dialog_content = "It's fine; I won't read them anyway...",
  ui_story_5065_50650406_4_dialog_content = "What I mean is I'm not in a hurry to read them.",
  ui_story_5065_50650406_5_dialog_content = "I see...",
  ui_story_5065_50650501_1_dialog_content = "Good morning, Your Honor!",
  ui_story_5065_50650501_2_dialog_content = "Morning!",
  ui_story_5065_50650501_3_dialog_content = "What tasks do you have for me today, sir?",
  ui_story_5065_50650501_4_dialog_content = "Quest? Oh, have you... have you been helping me catch those thieves recently?",
  ui_story_5065_50650501_5_dialog_content = "Yes sir! Earning your trust on my first day as a trainee and helping you solve important cases like this has been a great honor for me!",
  ui_story_5065_50650501_6_dialog_content = "Haha, you've been a great help. Thanks to you, my work's been going smoothly lately.",
  ui_story_5065_50650501_7_dialog_content = "Do those thieves have any other accomplices at large?",
  ui_story_5065_50650501_8_dialog_content = "Other accomplices? I don't think so. Don't bother about it.",
  ui_story_5065_50650501_9_dialog_content = "Besides, there's nothing much going on here now. You can head back. Thanks for these days.",
  ui_story_5065_50650501_10_dialog_content = "Er, but Your Honor...",
  ui_story_5065_50650501_11_dialog_content = "Is there something else?",
  ui_story_5065_50650501_12_dialog_content = "N-No sir, I just noticed that you seem a lot kinder than usual today.",
  ui_story_5065_50650501_13_dialog_content = "But now I finally understand! You were just playing the role of a harsh instructor these past few days!",
  ui_story_5065_50650501_14_dialog_content = "Because only a harsh instructor can produce exemplary students! Thank you so much for guiding me so well...",
  ui_story_5065_50650501_15_dialog_content = "Huh? N-no need to thank me, hahaha...",
  ui_story_5065_50650501_16_dialog_content = "Although it was brief, I will always cherish the time I spent working under you, Junior Judge!",
  ui_story_5065_50650502_1_dialog_content = "Good day, instructor!",
  ui_story_5065_50650502_2_dialog_content = "Pam? Aren't you supposed to be at the Hall of Justice right now?",
  ui_story_5065_50650502_3_dialog_content = "I have completed the initiate tasks given to me by the Hall of Justice, so the Junior Judge allowed me to come back sooner.",
  ui_story_5065_50650502_4_dialog_content = "Junior Judge, is that so?",
  ui_story_5065_50650502_5_dialog_content = "Hmm?",
  ui_story_5065_50650502_6_dialog_content = "(What's the Junior Judge doing here too?)",
  ui_story_5065_50650502_7_dialog_content = "(Ahhh... I was so emotional when we said goodbye earlier, so seeing him again so soon feels a little awkward.)",
  ui_story_5065_50650502_8_dialog_content = "I never told Pam that the quest was completed, did I?",
  ui_story_5065_50650502_9_dialog_content = "Huh? But back at the Hall of Justice, you said...",
  ui_story_5065_50650502_10_dialog_content = "I didn't even go to the Hall of Justice today! Oh, I see what's happening here; you're trying to skip out on work, aren't you?",
  ui_story_5065_50650502_11_dialog_content = "And here I was, coming to meet your mentor, hoping to extend your time as a trainee at the Hall of Justice.",
  ui_story_5065_50650502_12_dialog_content = "Geez, you really can't judge people by their looks these days, especially those young ones.",
  ui_story_5065_50650502_13_dialog_content = "Looks like I'll have to personally go after the leader of the thief gang.",
  ui_story_5065_50650502_14_dialog_content = "Wh-What did you say?!",
  ui_story_5065_50650502_15_dialog_content = "Then the person I spoke to in the Hall of Justice...",
  ui_story_5065_50650502_16_dialog_content = "Oh no!!!",
  ui_story_5065_50650502_17_dialog_content = "We need to go back and stop that man!",
  ui_story_5065_50650503_1_dialog_content = "Guards, where have the thieves we arrested a few days ago been confined?",
  ui_story_5065_50650503_2_dialog_content = "Are you planning to interrogate them? Please come with me.",
  ui_story_5065_50650503_3_dialog_content = "Wait!",
  ui_story_5065_50650503_4_dialog_content = "You again? Why are you back here?",
  ui_story_5065_50650503_5_dialog_content = "You're not going to interrogate those thieves! You're going to free them, aren't you?!",
  ui_story_5065_50650503_6_dialog_content = "You... You've got some nerve! A mere trainee, and you dare to question me?",
  ui_story_5065_50650503_7_dialog_content = "Because I didn't come here alone.",
  ui_story_5065_50650503_8_dialog_content = "What?",
  ui_story_5065_50650503_9_dialog_content = "Impersonating a significant member of the Hall of Justice, you're adding another charge to your list.",
  ui_story_5065_50650503_10_dialog_content = "!!!",
  ui_story_5065_50650503_11_dialog_content = "Guards, apprehend the thief in front of you!",
  ui_story_5065_50650503_12_dialog_content = "White Night up high, I can't believe these thieves were so cunning...",
  ui_story_5065_50650503_13_dialog_content = "It's all thanks to you that I could wrap up this case smoothly.",
  ui_story_5065_50650503_14_dialog_content = "I wanted you to stay a bit longer in the Hall of Justice, but your mentor was dead set against it.",
  ui_story_5065_50650503_15_dialog_content = "I'm already missing the days when you were working for me...",
  ui_story_5065_50650503_16_dialog_content = "Sigh... Keep it up! If you ever get the chance, be sure to apply for a position in the Hall of Justice!",
  ui_story_5065_50650503_17_dialog_content = "Thank you so much for trusting in me, Your Honor. I'll be sure to come back and see you someday!",
  ui_story_5065_50650601_1_dialog_content = "Pam, I've already heard a bit about your performance in the Hall of Justice from the Junior Judge.",
  ui_story_5065_50650601_2_dialog_content = "The Junior Judge wanted you to extend your stay with him for a few more days, but don't worry, I turned him down.",
  ui_story_5065_50650601_3_dialog_content = "As a trainee, your primary task now is to get to know the affiliations under the Lumopolis Temple inside out; that's what your role rotations are all about.",
  ui_story_5065_50650601_4_dialog_content = "Have you ever thought about where you'd like to do your next training?",
  ui_story_5065_50650601_5_dialog_content = "I haven't thought about it since I've only been following your orders.",
  ui_story_5065_50650601_6_dialog_content = "But if I was given a choice, then the place where I want to study the most is clear—Inside the Lumopolis Temple!",
  ui_story_5065_50650601_7_dialog_content = "Have you ever heard of the Heretics Investigation Division under the Lumopolis Temple's direct command?",
  ui_story_5065_50650601_8_dialog_content = "Do you mean the group protecting and affirming the people's faith in the God of Light?",
  ui_story_5065_50650601_9_dialog_content = "I heard only the best students can join the Investigation Division. I also heard... That you are one of them.",
  ui_story_5065_50650601_10_dialog_content = "You're in the know, I must say.",
  ui_story_5065_50650601_11_dialog_content = "Right now, you have an opportunity to help out the Investigation Division. Are you willing to give it a try?",
  ui_story_5065_50650601_12_dialog_content = "O-Of course! But... is someone like me really worthy of joining the Investigation Division?",
  ui_story_5065_50650601_13_dialog_content = "The Investigation Division is in dire need of manpower lately. If you excel during the support phase, you may indeed become a formal member in the future.",
  ui_story_5065_50650601_14_dialog_content = "But I must warn you, the duties of the Investigation Division are far more perilous than those of the Hall of Justice.",
  ui_story_5065_50650601_15_dialog_content = "With greater peril comes greater trust and honor. I'm willing to accept the risks!",
  ui_story_5065_50650601_16_dialog_content = "Good to hear. Lately, there have been reports of members of the True Order promoting suspicious beliefs infiltrating Lumopolis.",
  ui_story_5065_50650601_17_dialog_content = "Their presence poses a serious threat to the faith and well-being of Lumopolis' citizens.",
  ui_story_5065_50650601_18_dialog_content = "There's intel suggesting that a few of them have slipped into Dawn Academy. I need you to help uncover their identities. Can you handle this task?",
  ui_story_5065_50650601_19_dialog_content = "White Night up high! I won't rest until I've driven each and every one of them from our pure and holy city!",
  ui_story_5065_50650602_1_dialog_content = "In the face of the Truth, you and I are but specks of dust.",
  ui_story_5065_50650602_2_dialog_content = "We must repent for failing to understand the truth in time and for trying to understand it.",
  ui_story_5065_50650602_3_dialog_content = "...",
  ui_story_5065_50650602_4_dialog_content = "Greetings. Have you come to learn about the True Order?",
  ui_story_5065_50650602_5_dialog_content = "White Night up high, you should feel ashamed of yourself!",
  ui_story_5065_50650603_1_dialog_content = "Good job for getting those infiltrators out of Dawn Academy so quickly! Impressive!",
  ui_story_5065_50650603_2_dialog_content = "It's not common for someone to achieve such results on their first solo task, even within the Lumopolis Temple.",
  ui_story_5065_50650603_3_dialog_content = "But the situation is far from optimistic right now. Word has it that they've also managed to infiltrate the Hall of Justice.",
  ui_story_5065_50650603_4_dialog_content = "Given your earlier experience at the Hall of Justice, you should know your way around there.",
  ui_story_5065_50650603_5_dialog_content = "Next, I'd like you to make another trip to the Hall of Justice.",
  ui_story_5065_50650604_1_dialog_content = "The beauty of this building is meant only to hide its flaws.",
  ui_story_5065_50650604_2_dialog_content = "Much like your laws that govern Lumopolis, their grandeur merely hides the countless loopholes hidden within them.",
  ui_story_5065_50650604_3_dialog_content = "... Don't you also wear those thorns to show how powerful you are to others?",
  ui_story_5065_50650604_4_dialog_content = "White Night up high, I vow to find an even more suitable owner for these thorns!",
  ui_story_5065_50650701_1_dialog_content = "Pam, what brings you here today? Did you forget something?",
  ui_story_5065_50650701_2_dialog_content = "Today is a day off.",
  ui_story_5065_50650701_3_dialog_content = "But our work has been so urgent lately...",
  ui_story_5065_50650701_4_dialog_content = "I know things are pretty tight right now, but as a trainee, you don't need to push yourself so hard for now.",
  ui_story_5065_50650701_5_dialog_content = "You see, you'll have plenty of busy days ahead of you in the future.",
  ui_story_5065_50650701_6_dialog_content = "Oh...",
  ui_story_5065_50650701_7_dialog_content = "So don't stress yourslef now.",
  ui_story_5065_50650701_8_dialog_content = "N-Not at all! I'm more than happy to devote every single day of my life to working for the Lumopolis Temple!",
  ui_story_5065_50650701_9_dialog_content = "You've been through a lot lately. Use this day off and spend some time with your families.",
  ui_story_5065_50650702_1_dialog_content = "Pam!",
  ui_story_5065_50650702_2_dialog_content = "Lady Irridon...? What is it now?",
  ui_story_5065_50650702_3_dialog_content = "While carrying out my orders, I got entangled with a group of strange guards...",
  ui_story_5065_50650702_4_dialog_content = "White Night up high, what kind of quarrel would they have with a Justice Knight?",
  ui_story_5065_50650702_5_dialog_content = "Don't tell me you provoked them by mistaking their identities as well?",
  ui_story_5065_50650702_6_dialog_content = "They aren't Lumo Guards at all! See for yourself!",
  ui_story_5065_50650702_7_dialog_content = "Protection! Loyalty! Glory!",
  ui_story_5065_50650702_8_dialog_content = "Huh? You're right, there is something strange about these guards!",
  ui_story_5065_50650702_9_dialog_content = "Attack!",
  ui_story_5065_50650702_10_dialog_content = "Those guards... How did they vanish just like that?",
  ui_story_5065_50650702_11_dialog_content = "It's rather odd, isn't it?",
  ui_story_5065_50650702_12_dialog_content = "Now I suppose you're going to tell me that this could only happen because we're in a dream world, yes?",
  ui_story_5065_50650702_13_dialog_content = "Thank goodness you're finally starting to believe me, Pam!",
  ui_story_5065_50650702_14_dialog_content = "... I don't believe you. This must be some sort of trick they learned somewhere.",
  ui_story_5065_50650702_15_dialog_content = "In any case, I will report this matter to the Lumopolis Temple.",
  ui_story_5065_50650702_16_dialog_content = "...",
  ui_story_5065_50650702_17_dialog_content = "If you'll excuse me, Lady Irridon, I need to visit my grandfather now. Good day.",
  ui_story_5065_50650702_18_dialog_content = "Pam...",
  ui_story_5065_50650703_1_dialog_content = "Why hasn't grandfather arranged for someone to clear the leaves from the front of his house?",
  ui_story_5065_50650703_2_dialog_content = "Let me help you sweep them up.",
  ui_story_5065_50650703_3_dialog_content = "You... Have you been following me again?!",
  ui_story_5065_50650703_4_dialog_content = "I'm here on family matters, so Justice Knight's help isn't needed.",
  ui_story_5065_50650703_5_dialog_content = "Now please go mind your own business!",
  ui_story_5065_50650704_1_dialog_content = "...",
  ui_story_5065_50650704_2_dialog_content = "Why are you still here, Lady Irridon?",
  ui_story_5065_50650704_3_dialog_content = "If you keep trying to convince me that this world is nothing but a dream, I'll have no choice but to suspect you of being a member of the True Order.",
  ui_story_5065_50650704_4_dialog_content = "I... I won't bother you by bringing that up anymore.",
  ui_story_5065_50650704_5_dialog_content = "Actually, I bought some ingredients to make food, but I don't know how to prepare them.",
  ui_story_5065_50650704_6_dialog_content = "I was told you're an excellent cook, so I wanted to ask for your help.",
  ui_story_5065_50650704_7_dialog_content = "Is that really the reason you've been following me around?",
  ui_story_5065_50650704_8_dialog_content = "... Yes.",
  ui_story_5065_50650704_9_dialog_content = "Hahaha, then you came to the right person! Here, let me see what you bought!",
  ui_story_5065_50650704_10_dialog_content = "Just some flour and some beans.",
  ui_story_5065_50650704_11_dialog_content = "This flour looks discolored and dingy, the beans are shriveled... Are you sure you weren't cheated by the person who sold them to you?",
  ui_story_5065_50650704_12_dialog_content = "I hear a lot of people in Lower Lumopolis can only afford ingredients like this, so I wanted to give them a try as well.",
  ui_story_5065_50650704_13_dialog_content = "Is this what the nobility finds trendy right now?",
  ui_story_5065_50650704_14_dialog_content = "I just want to have a clearer idea of how the other people in Lumopolis live.",
  ui_story_5065_50650704_15_dialog_content = "If I can find a way to turn these ingredients into something delicious, I can share the recipe with everyone.",
  ui_story_5065_50650704_16_dialog_content = "... I had no idea you had this side to you, Lady Irridon.",
  ui_story_5065_50650704_17_dialog_content = "With enough care and dedication, you can make delicious food out of any ingredients. Just a moment, please!",
  ui_story_5065_50650704_18_dialog_content = "<color=#e8d9bb>Some time later...</color>",
  ui_story_5065_50650704_19_dialog_content = "Sorry to have kept you waiting! Here, give it a try!",
  ui_story_5065_50650704_20_dialog_content = "This flavor... It tastes exactly the same...",
  ui_story_5065_50650704_21_dialog_content = "This tastes just like the first time I had it!",
  ui_story_5065_50650704_22_dialog_content = "Really? What an odd coincidence. Who made it for you last time?",
  ui_story_5065_50650704_23_dialog_content = "Even after making this, you still don't remember anything, do you Pam?",
  ui_story_5065_50650704_24_dialog_content = "I knew it. You weren't trying to learn a new recipe from me at all, Lady Irridon.",
  ui_story_5065_50650704_25_dialog_content = "I still need to see my grandfather, so please forgive me for asking you to leave so soon. Also...",
  ui_story_5065_50650704_26_dialog_content = "You should take the time to see a doctor, Lady Irridon. I'm greatly concerned for your mental health.",
  ui_story_5065_50650704_27_dialog_content = "Sigh...",
  ui_story_5065_50650704_28_dialog_content = "I failed yet again.",
  ui_story_5065_50650704_29_dialog_content = "You haven't failed yet... We still have another chance!",
  ui_story_5065_50650704_30_dialog_content = "Just don't give up!!!",
  ui_story_5065_50650704_31_dialog_content = "... You're right. I can't just give up like this.",
  ui_story_5065_50650704_32_dialog_content = "I finally understand just how hard it was for you to wake me up...",
  ui_story_5065_50650704_33_dialog_content = "But don't worry. I'm more than capable of doing this now.",
  ui_story_5065_50650801_1_dialog_content = "Good morning, instructor!",
  ui_story_5065_50650801_2_dialog_content = "Pam, feeling better after the rest?",
  ui_story_5065_50650801_3_dialog_content = "I feel very well rested, thank you for asking. I'm also looking forward to starting my next task!",
  ui_story_5065_50650801_4_dialog_content = "Thanks to your help these days, we've cleared out all the True Order infiltrators from the Lumopolis Gardens.",
  ui_story_5065_50650801_5_dialog_content = "But there are still signs of their activities beyond the Lumopolis Gardens. We need to keep the momentum going and chase them down.",
  ui_story_5065_50650801_6_dialog_content = "Understood. I'll be sure to flush out every last one of them!",
  ui_story_5065_50650801_7_dialog_content = "They're good at staying hidden, so we'll need you to patrol and keep a sharp lookout.",
  ui_story_5065_50650801_8_dialog_content = "Understood!",
  ui_story_5065_50650802_1_dialog_content = "Do you want to know the secret beneath my right eye?",
  ui_story_5065_50650802_2_dialog_content = "I promise you, join us in the True Order, and you'll find out more and more secrets.",
  ui_story_5065_50650802_3_dialog_content = "... About my right eye, or the filthy teachings of this city.",
  ui_story_5065_50650802_4_dialog_content = "Lumopolis is a pure city which will never fall. How could it have any filthy teachings as you claim?!",
  ui_story_5065_50650802_5_dialog_content = "Your ramblings are nothing more than vague and confusing heresy!",
  ui_story_5065_50650803_1_dialog_content = "Great job, Pam!",
  ui_story_5065_50650803_2_dialog_content = "The streets in Lumopolis Courtyard are clean and serene again, all thanks to you.",
  ui_story_5065_50650803_3_dialog_content = "But those outlaws have taken the chance to flee to Lower Lumopolis.",
  ui_story_5065_50650803_4_dialog_content = "The population in that district is a diverse mix of people, and the residents' faith is not strong enough, which makes it our primary focus.",
  ui_story_5065_50650803_5_dialog_content = "The seniors from the Investigation Division are already on the chase in Lower Lumopolis. You should go and help them out.",
  ui_story_5065_50650803_6_dialog_content = "I would be happy to work alongside my superiors!",
  ui_story_5065_50650804_1_dialog_content = "...",
  ui_story_5065_50650804_2_dialog_content = "Why are you cowering in the corner, Miss? Are you feeling unwell?",
  ui_story_5065_50650804_3_dialog_content = "I... I'm fine. I just have no way of completing the task they gave me...",
  ui_story_5065_50650804_4_dialog_content = "They were kind to me, and I really wanted to help them... But I'm just too useless.",
  ui_story_5065_50650804_5_dialog_content = "What is your task? Perhaps I can help you?",
  ui_story_5065_50650804_6_dialog_content = "It was... to convince everyone to join the True Order.",
  ui_story_5065_50650804_7_dialog_content = "What?!",
  ui_story_5065_50650804_8_dialog_content = "Forgive me for treating you so unkindly... But I have no other choice.",
  ui_story_5065_50650901_1_dialog_content = "Pam, here you are.",
  ui_story_5065_50650901_2_dialog_content = "Yes. Do you have another task for me?",
  ui_story_5065_50650901_3_dialog_content = "Not me; it's a teacher from Dawn Academy looking for you. He wants you to come back to school and help out.",
  ui_story_5065_50650901_4_dialog_content = "He's looking for me? I wonder why...?",
  ui_story_5065_50650901_5_dialog_content = "It's got something to do with his recent research, it seems.",
  ui_story_5065_50650901_6_dialog_content = "Thank you. I'll return to the Academy right away!",
  ui_story_5065_50650902_1_dialog_content = "Hello, sir. Did you need my help with something?",
  ui_story_5065_50650902_2_dialog_content = "Pam, it's great to have you back!",
  ui_story_5065_50650902_3_dialog_content = "You might have heard that I've been conducting research on \"object weight at different heights.\"",
  ui_story_5065_50650902_4_dialog_content = "I believe that an object is lighter in Lumopolis Gardens than in Lower Lumopolis.",
  ui_story_5065_50650902_5_dialog_content = "Recently, my research has entered its final empirical stage.",
  ui_story_5065_50650902_6_dialog_content = "If this hypothesis can be proven right, it'll spark a revolutionary wave in the academic community of Lumopolis!",
  ui_story_5065_50650902_7_dialog_content = "Do you know why?",
  ui_story_5065_50650902_8_dialog_content = "I-I can't say I do, but please explain!",
  ui_story_5065_50650902_9_dialog_content = "Because once this hypothesis is proven, it will show that the God of Light has taken away a significant weight from Lumopolis Gardens!",
  ui_story_5065_50650902_10_dialog_content = "Which means the Lumopolis Gardens is more favored by the God of Light, and the citizens here should receive greater respect and support from the populace!",
  ui_story_5065_50650902_11_dialog_content = "In other words, as long as we pray sincerely, the God of Light will surely take notice...",
  ui_story_5065_50650902_12_dialog_content = "But with no academic achievements to speak of, how could I possibly help you?",
  ui_story_5065_50650902_13_dialog_content = "As a trainee, you have access to the scale statues in Lumopolis.",
  ui_story_5065_50650902_14_dialog_content = "I'd like you to go to the Hall of Justice's entrance, the Lumopolis Courtyard, and Lower Lumopolis and measure the weight of this golden weight separately.",
  ui_story_5065_50650902_15_dialog_content = "Absolutely no faking or cheating. Do you get my point?",
  ui_story_5065_50650902_16_dialog_content = "I understand, professor. If the measurements show that the golden weight is heaviest in Lower Lumopolis, then it confirms your hypothesis!",
  ui_story_5065_50650902_17_dialog_content = "What a glorious achievement it is to prove the existence of the God of Light's blessings...",
  ui_story_5065_50650902_18_dialog_content = "Thank you for allowing me to be a part of this experiment, professor! I'll give it my all!",
  ui_story_5065_50650903_1_dialog_content = "So the only way to gather these measurements is by completing a Quest of Scales...",
  ui_story_5065_50650903_2_dialog_content = "But it's fine! I had to complete a similar quest before, so this one shouldn't be a problem!",
  ui_story_5065_50650903_3_dialog_content = "One golden weight is equal to... three silver weights.",
  ui_story_5065_50650903_4_dialog_content = "Good! I should take clear notes of all my findings!",
  ui_story_5065_50650904_1_dialog_content = "Hmm, one golden weight is equal to... Three silver weights again?",
  ui_story_5065_50650904_2_dialog_content = "This is likely because the difference in altitude between the Lumopolis Gardens and the Lumopolis Courtyard is relatively small...",
  ui_story_5065_50650905_1_dialog_content = "How could this be...?",
  ui_story_5065_50650905_2_dialog_content = "The golden weight is equal to three silver weights, no matter where I go!!",
  ui_story_5065_50650905_3_dialog_content = "Could I have measured incorrectly?",
  ui_story_5065_50650905_4_dialog_content = "I-It couldn't be, I followed the instructions for the scales perfectly. There can be no mistake...",
  ui_story_5065_50650905_5_dialog_content = "I'll just have to report my findings to the professor.",
  ui_story_5065_50650906_1_dialog_content = "What?!",
  ui_story_5065_50650906_2_dialog_content = "No way! How could the results of the three measurements be the same?!",
  ui_story_5065_50650906_3_dialog_content = "Is it possible my theory is flawed? Or could there be an issue with the experiment subjects I selected? Or maybe...",
  ui_story_5065_50650906_4_dialog_content = "Maybe the staff of the experiment is not blessed by the God of Light?",
  ui_story_5065_50650906_5_dialog_content = "P-Professor, I can assure you that I made no mistakes when taking those measurements...",
  ui_story_5065_50650906_6_dialog_content = "I know, it's not your fault.",
  ui_story_5065_50650906_7_dialog_content = "I'll look into it more closely to find out which step went wrong. When I figure it out, I might need your help again.",
  ui_story_5065_50650906_8_dialog_content = "You can head back for today.",
  ui_story_5065_50650906_9_dialog_content = "Very well, professor. Have a nice day...",
  ui_story_5065_50651001_1_dialog_content = "Do you have any other tasks for me, instructor?",
  ui_story_5065_50651001_2_dialog_content = "Well, you've come at just the right time.",
  ui_story_5065_50651001_3_dialog_content = "Not long ago, we ousted some True Order members who had infiltrated Lower Lumopolis.",
  ui_story_5065_50651001_4_dialog_content = "But there's evidence indicating that they still have some members lurking there, doing illegal preaching.",
  ui_story_5065_50651001_5_dialog_content = "As I said earlier, the faith of the Lower Lumopolis residents is fragile, making them easy targets for the True Order's influence.",
  ui_story_5065_50651001_6_dialog_content = "Hence, we should organize more lectures about the God of Light in Lower Lumopolis.",
  ui_story_5065_50651001_7_dialog_content = "I've reviewed your performance at Dawn Academy, so I'm confident in sending you there for the relevant lecture duties.",
  ui_story_5065_50651001_8_dialog_content = "Your lectures should be given at the square in Lower Lumopolis.",
  ui_story_5065_50651001_9_dialog_content = "This... This is what I've dreamed about for so long! I promise I won't disappoint you!",
  ui_story_5065_50651002_1_dialog_content = "Pardon me... But could you point me in the direction of the square in Lower Lumopolis?",
  ui_story_5065_50651002_2_dialog_content = "My dear lady, the place you seek is right beneath your feet!",
  ui_story_5065_50651002_3_dialog_content = "May I ask if you require assistance?",
  ui_story_5065_50651002_4_dialog_content = "Thank you for letting me know. I'm here to deliver a number of small sermons.",
  ui_story_5065_50651002_5_dialog_content = "This is my first time speaking to the public like this, so I'm feeling a bit nervous.",
  ui_story_5065_50651002_6_dialog_content = "That's perfectly normal.",
  ui_story_5065_50651002_7_dialog_content = "Everyone gets nervous at times, even those who have delivered thousands of speeches in their lives.",
  ui_story_5065_50651002_8_dialog_content = "You must simply learn to enjoy your nervousness. Appreciate the elevated heartbeat and the stimulating sweat on your palms.",
  ui_story_5065_50651002_9_dialog_content = "That very same stimulation will help you deliver an even more impactful speech.",
  ui_story_5065_50651002_10_dialog_content = "I'm just worried that my words won't draw the people's attention.",
  ui_story_5065_50651002_11_dialog_content = "A simple enough task. Allow me to help you gather an audience.",
  ui_story_5065_50651002_12_dialog_content = "Huh?",
  ui_story_5065_50651002_13_dialog_content = "<color=#e8d9bb>In no time, the square is filled with citizens of all ages, and Pam begins her teaching smoothly.</color>",
  ui_story_5065_50651002_14_dialog_content = "... And so, this concludes the teachings I wish to share with you today.",
  ui_story_5065_50651002_15_dialog_content = "In summation, so long as your heart is full of repentance, the God of Light shall bless you with his divine forgiveness!",
  ui_story_5065_50651002_16_dialog_content = "Alas, it's a pity that one's fate can't be changed through faith.",
  ui_story_5065_50651002_17_dialog_content = "What makes you say that, sir?",
  ui_story_5065_50651002_18_dialog_content = "...",
  ui_story_5065_50651002_19_dialog_content = "Huh? Wait... Please don't go!",
  ui_story_5065_50651003_1_dialog_content = "Where did that older gentleman go? I simply wanted to ask him to share his woes with me...",
  ui_story_5065_50651003_2_dialog_content = "Ladies and gentlemen!",
  ui_story_5065_50651003_3_dialog_content = "Huh? It's that kind-hearted man from before... Is he giving a speech here as well?",
  ui_story_5065_50651003_4_dialog_content = "There are times when ideologies must conflict in order to truly shine.",
  ui_story_5065_50651003_5_dialog_content = "And right now, the voice of the future cries out as the tides of Truth surge! All who believe will ultimately know salvation!",
  ui_story_5065_50651003_6_dialog_content = "Join us, and be blessed with everlasting joy!",
  ui_story_5065_50651003_7_dialog_content = "Are you with the True Order?",
  ui_story_5065_50651003_8_dialog_content = "Oh no... He was using me just now!",
  ui_story_5065_50651101_1_dialog_content = "Are there still any members of the True Order sowing discord in Lumopolis, instructor?",
  ui_story_5065_50651101_2_dialog_content = "Thanks to your help, the Investigation Division has expelled all active heretics from our midst.",
  ui_story_5065_50651101_3_dialog_content = "I understand you must be reluctant, but your training with the Investigation Division is about to conclude.",
  ui_story_5065_50651101_4_dialog_content = "Is it because my performance wasn't satisfactory?",
  ui_story_5065_50651101_5_dialog_content = "Of course not. I now understand why the Junior Judge insisted on having you stay with the Hall of Justice.",
  ui_story_5065_50651101_6_dialog_content = "Your work capabilities are excellent, and you have successfully resolved many problems, relieving your colleagues of their workload.",
  ui_story_5065_50651101_7_dialog_content = "Even I would like to keep you in the Investigation Division working like this.",
  ui_story_5065_50651101_8_dialog_content = "However, another tricky issue has emerged recently... Many Eclipsites have suddenly appeared in Lumopolis.",
  ui_story_5065_50651101_9_dialog_content = "All Lumo Knights have been mobilized, but we still haven't discovered why the Eclipsites are pouring in.",
  ui_story_5065_50651101_10_dialog_content = "The Lumo Knights are seeking the support of trainees with combat skills. I believe you are the best fit for the job.",
  ui_story_5065_50651101_11_dialog_content = "Our top priority at the moment is to ensure the safety of Lumopolis Gardens.",
  ui_story_5065_50651101_12_dialog_content = "I'd like you to report to the Guard Captain of Lumopolis Gardens and lend her a hand. Pam, are you up for it?",
  ui_story_5065_50651101_13_dialog_content = "I have no objections! But where can I find the Guard Captain of the Lumopolis Gardens?",
  ui_story_5065_50651101_14_dialog_content = "The whereabouts of the Lumo Knights on this mission are top-secret and can't be shared casually.",
  ui_story_5065_50651101_15_dialog_content = "But she left you with a riddle—",
  ui_story_5065_50651101_16_dialog_content = "She's at the \"place closest to the sky.\"",
  ui_story_5065_50651101_17_dialog_content = "A riddle... Is she testing me?",
  ui_story_5065_50651101_18_dialog_content = "That's one way to see it. But with your abilities, you should be able to find the location indicated by the riddle soon, right?",
  ui_story_5065_50651101_19_dialog_content = "I-I'll do my best!",
  ui_story_5065_50651102_1_dialog_content = "Greetings! Pardon me, but are you the Guard Captain of the Lumopolis Gardens?",
  ui_story_5065_50651102_2_dialog_content = "And you are...?",
  ui_story_5065_50651102_3_dialog_content = "My name is Paloma. I'm an initiate.",
  ui_story_5065_50651102_4_dialog_content = "You're Pam, right? I've heard about you from your mentor. Looks like that riddle couldn't stump you at all.",
  ui_story_5065_50651102_5_dialog_content = "Congrats, you aced the first test.",
  ui_story_5065_50651102_6_dialog_content = "Things are pretty urgent right now, so I have to send you out to check the area as soon as possible. Hope that's okay with you.",
  ui_story_5065_50651102_7_dialog_content = "I don't mind at all! I'm happy to start right away and help eliminate this threat!",
  ui_story_5065_50651102_8_dialog_content = "Very well. Your mission is relatively simple—I hope you can go to Dawn Academy and investigate if there are any hideouts of the Eclipsites there.",
  ui_story_5065_50651102_9_dialog_content = "The Dawn Academy... I won't allow any Eclipsites to desecrate the halls of learning where I once studied!",
  ui_story_5065_50651201_1_dialog_content = "Good morning, Guard Captain!",
  ui_story_5065_50651201_2_dialog_content = "Morning, I heard you rescued a bunch of juniors from the Eclipsites?",
  ui_story_5065_50651201_3_dialog_content = "White Night up high! Protecting the innocent and eradicating the Eclipsites... I was simply doing what should be done!",
  ui_story_5065_50651201_4_dialog_content = "No need for modesty. At first, I thought your mentor's compliments were a bit much, but now I see they were spot on.",
  ui_story_5065_50651201_5_dialog_content = "Based on the patrol report you submitted, did you conclude that there are no hiding places for the Eclipsites at Dawn Academy?",
  ui_story_5065_50651201_6_dialog_content = "While there are still occasional sightings of Eclipsites causing trouble in Lumopolis Gardens, it seems that they didn't infiltrate from within.",
  ui_story_5065_50651201_7_dialog_content = "In that case, it would be a waste to keep you here.",
  ui_story_5065_50651201_8_dialog_content = "How about this? You go find the Forest Knight Commander and see if there are any Eclipsites hideouts in her jurisdiction.",
  ui_story_5065_50651201_9_dialog_content = "She is at the \"spot facing the scale\"...",
  ui_story_5065_50651201_10_dialog_content = "Another riddle...?",
  ui_story_5065_50651202_1_dialog_content = "Greetings! Excuse me, but are you the Forest Knight Commander?",
  ui_story_5065_50651202_2_dialog_content = "Hi there! You must be Pam!",
  ui_story_5065_50651202_3_dialog_content = "Mmm, you look like a good kid. I've been looking forward to meeting you!",
  ui_story_5065_50651202_4_dialog_content = "Where should I begin my investigation, Knight Commander?",
  ui_story_5065_50651202_5_dialog_content = "Pam, you're quite the eager beaver, aren't you?",
  ui_story_5065_50651202_6_dialog_content = "Alright, let's see... Hmmm, it looks like there's a bit of a workforce shortage around the noble residences.",
  ui_story_5065_50651202_7_dialog_content = "So, Pam, I'll need you to go support the patrols and investigations over there. And be sure to stay safe!",
  ui_story_5065_50651204_1_dialog_content = "Oh dear! With your help, Pam, the investigation has really picked up speed.",
  ui_story_5065_50651204_2_dialog_content = "Turns out the Eclipsites' hideout isn't near the residential area, is it? That's a big relief.",
  ui_story_5065_50651204_3_dialog_content = "Well, that leaves just one place...",
  ui_story_5065_50651204_4_dialog_content = "The square near the scale sculpture, a crucial path leading to Lower Lumopolis, is indeed worth looking into.",
  ui_story_5065_50651204_5_dialog_content = "Pam, now it's your job to investigate there.",
  ui_story_5065_50651301_1_dialog_content = "Sigh... This's really a headache...",
  ui_story_5065_50651301_2_dialog_content = "Is something the matter, Knight Commander?",
  ui_story_5065_50651301_3_dialog_content = "We've caught an Eclipsite that can speak the Universese and plan to interrogate it thoroughly about how it sneaked into Lumopolis.",
  ui_story_5065_50651301_4_dialog_content = "But that Eclipsite won't say a word, no matter what...",
  ui_story_5065_50651301_5_dialog_content = "Hmm, I wonder if there's any other way to make it talk?",
  ui_story_5065_50651301_6_dialog_content = "Oh my! Now that you mention it, I suddenly recall a long-standing folk trick.",
  ui_story_5065_50651301_7_dialog_content = "It's said that sprinkling Chattergrass Essence on the Golden Weight and then pressing it on the culprit's head will make them talk.",
  ui_story_5065_50651301_8_dialog_content = "I'm just not so sure if this trick will work on Eclipsites.",
  ui_story_5065_50651301_9_dialog_content = "A golden weight shouldn't be a problem, but where can I find Chattergrass Essence?",
  ui_story_5065_50651301_10_dialog_content = "Mmm, I believe the teachers at Dawn Academy should know how to refine the Chattergrass Essence.",
  ui_story_5065_50651301_11_dialog_content = "And, for that trick to work, the Golden Weight has to be the one obtained from the scale in front of the Hall of Justice.",
  ui_story_5065_50651301_12_dialog_content = "That doesn't sound too difficult. I'll go help you look!",
  ui_story_5065_50651302_1_dialog_content = "Whew! I got a golden weight!",
  ui_story_5065_50651302_2_dialog_content = "Now all that leaves is the Chattergrass Essence.",
  ui_story_5065_50651302_3_dialog_content = "Right! Time to try my luck with the professor at the Dawn Academy!",
  ui_story_5065_50651303_1_dialog_content = "Pam, why are you looking around? Are you searching for someone?",
  ui_story_5065_50651303_2_dialog_content = "I was searching for you, professor! Do you happen to know about Chattergrass Essence?",
  ui_story_5065_50651303_3_dialog_content = "Haha, botany is my strong suit. You've asked the right person.",
  ui_story_5065_50651303_4_dialog_content = "Chattergrass Essence is something I stumbled upon and synthesized by chance.",
  ui_story_5065_50651303_5_dialog_content = "White Night up high! The God of Light must have guided me to you, professor!",
  ui_story_5065_50651303_6_dialog_content = "The Lumo Knights urgently require this essence. Could I possibly trouble you for some?",
  ui_story_5065_50651303_7_dialog_content = "It's no trouble at all. If you need it, I can gather and refine it for you anytime.",
  ui_story_5065_50651303_8_dialog_content = "The Chattergrass garden I tend to is littered with leaves. I haven't had time to tidy it up...",
  ui_story_5065_50651303_9_dialog_content = "Leave it to me, professor! I'll help you tidy it up!",
  ui_story_5065_50651303_10_dialog_content = "Mmm, well done. You've done a thorough job cleaning—much better than those unreliable juniors of yours.",
  ui_story_5065_50651303_11_dialog_content = "Here, consider this bottle of Chattergrass Essence a gift from me.",
  ui_story_5065_50651303_12_dialog_content = "Whenever you have some free time in the future, do drop by to see me and maybe lend a hand in tidying up the lawn.",
  ui_story_5065_50651304_1_dialog_content = "Oh my, you really found both of these?!",
  ui_story_5065_50651304_2_dialog_content = "And you managed to do it in such a short time...",
  ui_story_5065_50651304_3_dialog_content = "Pam, you've done me a big favor once again!",
  ui_story_5065_50651304_4_dialog_content = "Sigh, I'm starting to feel a bit reluctant to let you go.",
  ui_story_5065_50651304_5_dialog_content = "After your training is over, would you consider becoming a member of us Lumo Knights?",
  ui_story_5065_50651304_6_dialog_content = "Make sure to give it some serious thought, okay?",
  ui_story_5065_50651401_1_dialog_content = "Hey, Pam, how did it go? Find where the Eclipsites are hiding?",
  ui_story_5065_50651401_2_dialog_content = "I believe the situation here is extremely similar to the one I encountered in the Lumopolis Gardens.",
  ui_story_5065_50651401_3_dialog_content = "While there were a number of rogue Eclipsites in the area, I didn't find anything that could be considered a hiding place for them.",
  ui_story_5065_50651401_4_dialog_content = "Since they didn't come from Lumopolis Gardens or Lumopolis Courtyard, there's only one possibility left.",
  ui_story_5065_50651401_5_dialog_content = "I know you've put in a lot of effort these days.",
  ui_story_5065_50651401_6_dialog_content = "But now, I still need you to help out the Water Knight Commander in the Lower Lumopolis.",
  ui_story_5065_50651401_7_dialog_content = "If the Eclipsites are truly hiding in the Lower Lumopolis, I'm a bit worried about her being there all alone.",
  ui_story_5065_50651401_8_dialog_content = "And, of course, don't let her know what I just said.",
  ui_story_5065_50651401_9_dialog_content = "Ah, I almost forgot to tell you that the Water Knight Commander is at the \"place between two green eyes.\"",
  ui_story_5065_50651401_10_dialog_content = "Understood. I'll find the Water Knight Commander and help her destroy the Eclipsites and their hidden gathering point!",
  ui_story_5065_50651402_1_dialog_content = "Huh?",
  ui_story_5065_50651402_2_dialog_content = "What's up, Miss? Why are you giving me such an odd look? Is something bothering you?",
  ui_story_5065_50651402_3_dialog_content = "Am I in the right place? Or could it be... That you are the Water Knight Commander?",
  ui_story_5065_50651402_4_dialog_content = "Yep, I am.",
  ui_story_5065_50651402_5_dialog_content = "Ah-ha, I get it now! You must be the one they've been mentioning—Pam! Good to finally meet you!",
  ui_story_5065_50651402_6_dialog_content = "There's indeed a shortage of manpower in the Lower Lumopolis right now, so I might have to trouble you with an outdoor patrol...",
  ui_story_5065_50651402_7_dialog_content = "It's no trouble at all! If you need me to patrol an area, just give me the order!",
  ui_story_5065_50651402_8_dialog_content = "Let me see... the only residential area left unchecked is near the scale sculpture. So that's where you need to patrol!",
  ui_story_5065_50651402_9_dialog_content = "Not a problem!",
  ui_story_5065_50651403_1_dialog_content = "There are more Eclipsites here than in the Lumopolis Gardens, and they're much stronger too.",
  ui_story_5065_50651403_2_dialog_content = "Could their secret gathering point be somewhere nearby?",
  ui_story_5065_50651404_1_dialog_content = "Roooaaar!",
  ui_story_5065_50651404_2_dialog_content = "This is the end!",
  ui_story_5065_50651404_3_dialog_content = "Phew... I never expected the Eclipsites to be hiding in a normal home like this.",
  ui_story_5065_50651404_4_dialog_content = "...",
  ui_story_5065_50651404_5_dialog_content = "Who's there? Show yourself!",
  ui_story_5065_50651404_6_dialog_content = "I'm going all out against you!!!",
  ui_story_5065_50651404_7_dialog_content = "It's you!",
  ui_story_5065_50651404_8_dialog_content = "... You know me?",
  ui_story_5065_50651404_9_dialog_content = "Don't you remember? When I was delivering my sermons in the city square the other day, you said...",
  ui_story_5065_50651404_10_dialog_content = "Alas, it's a pity that one's fate can't be changed through faith.",
  ui_story_5065_50651404_11_dialog_content = "At the time, I really wanted to ask why you said such a thing and what you were prepared to do about it, but you left in such a hurry...",
  ui_story_5065_50651404_12_dialog_content = "(cough) And now you see it.",
  ui_story_5065_50651404_13_dialog_content = "Yes... It's me who has concealed the Eclipsites in my house! I want to take revenge on Lumopolis! Come on! Execute me! Coughs...",
  ui_story_5065_50651404_14_dialog_content = "Are you injured? Please forgive me, I didn't hurt you just now, did I?",
  ui_story_5065_50651404_15_dialog_content = "Stop being so hypocritical, cough... W-Why do you want to heal me?",
  ui_story_5065_50651404_16_dialog_content = "I don't know what happened in your past, nor do I know why you wish to take revenge on Lumopolis.",
  ui_story_5065_50651404_17_dialog_content = "But you are still my fellow citizen! A living, breathing citizen!",
  ui_story_5065_50651404_18_dialog_content = "White Night up high! The God of Light teaches us to love and aid our fellow citizens, and to show them compassion...",
  ui_story_5065_50651404_19_dialog_content = "I won't stand idly by and watch as you suffer!",
  ui_story_5065_50651404_20_dialog_content = "Who are you, really?",
  ui_story_5065_50651404_21_dialog_content = "My name is Paloma, but you can call me Pam. I am an initiate of the temple.",
  ui_story_5065_50651404_22_dialog_content = "Heh... So, turns out innocent and kind-hearted kids like you do exist in this world.",
  ui_story_5065_50651404_23_dialog_content = "If only I had met ones as genuine as you back then, maybe I wouldn't have come to this point today...",
  ui_story_5065_50651404_24_dialog_content = "However, kid, in a city like this, innocence and kindness don't get you far.",
  ui_story_5065_50651404_25_dialog_content = "I hope that you... won't face the same unfairness I did...",
  ui_story_5065_50651404_26_dialog_content = "Wh-What are you planning to do?",
  ui_story_5065_50651404_27_dialog_content = "Thank you for allowing me to feel a hint of warmth in the final moments of my life.",
  ui_story_5065_50651404_28_dialog_content = "Farewell, kid.",
  ui_story_5065_50651404_29_dialog_content = "<color=#e8d9bb>The old man reaches into his waist and pulls out a dagger, viciously thrusting it into his own heart.</color>",
  ui_story_5065_50651404_30_dialog_content = "...!!!",
  ui_story_5065_50651404_31_dialog_content = "Why... Why would you do this...?",
  ui_story_5065_50651501_1_dialog_content = "Pam... Wh-What a coincidence!",
  ui_story_5065_50651501_2_dialog_content = "(Sigh, you're a terrible liar, Irridon...)",
  ui_story_5065_50651501_3_dialog_content = "Lady Irridon? What are you doing here as well...?",
  ui_story_5065_50651501_4_dialog_content = "I... I'm here for work, of course! Justice Knights are known to run about like this every so often.",
  ui_story_5065_50651501_5_dialog_content = "U-Unfortunately, I lost a very important file, and now I'm desperately searching for it.",
  ui_story_5065_50651501_6_dialog_content = "They say you're really skilled at finding missing items, Pam... Could you help me look?",
  ui_story_5065_50651501_7_dialog_content = "A very important file?",
  ui_story_5065_50651501_8_dialog_content = "Yes! It's extremely important! If I don't find it, they might kick me out of the Hall of Justice!",
  ui_story_5065_50651501_9_dialog_content = "Sigh, if it's truly that important, you should have taken better care of it in the first place.",
  ui_story_5065_50651501_10_dialog_content = "Where have you been recently?",
  ui_story_5065_50651501_11_dialog_content = "Well, I just walked over here from that statue of the scales.",
  ui_story_5065_50651501_12_dialog_content = "... Very well, I'll help you.",
  ui_story_5065_50651502_1_dialog_content = "Ugh, why would someone litter such a neat and tidy street with so much shredded paper?",
  ui_story_5065_50651502_2_dialog_content = "Wait, could that file be hidden somewhere under all of this paper?",
  ui_story_5065_50651502_3_dialog_content = "I can't rule out a single possibility, so I'll have to give this place a good cleaning!",
  ui_story_5065_50651502_4_dialog_content = "There's nothing here...",
  ui_story_5065_50651502_5_dialog_content = "I suppose I'll just have to keep looking ahead.",
  ui_story_5065_50651503_1_dialog_content = "Why has no one cleaned up all of these leaves, either?",
  ui_story_5065_50651503_2_dialog_content = "Ugh... I still can't rule out any possibilities.",
  ui_story_5065_50651503_3_dialog_content = "Cleaning up these leaves shouldn't take long anyway.",
  ui_story_5065_50651503_4_dialog_content = "Phew! Much cleaner!",
  ui_story_5065_50651503_5_dialog_content = "But still no sign of that file...",
  ui_story_5065_50651504_1_dialog_content = "Thank goodness! This should be the missing file!",
  ui_story_5065_50651504_2_dialog_content = "But it was in plain sight near the statue of the scales... How could Lady Irridon have missed it?",
  ui_story_5065_50651505_1_dialog_content = "Lady Irridon, is this your missing file?",
  ui_story_5065_50651505_2_dialog_content = "... Did you happen to take a look at its contents?",
  ui_story_5065_50651505_3_dialog_content = "I may not be officially employed by the Hall of Justice, but even I know that looking at personal files is unacceptable.",
  ui_story_5065_50651505_4_dialog_content = "I believe you should be the one to check it.",
  ui_story_5065_50651505_5_dialog_content = "It shouldn't be a problem. In fact, I was hoping you would take a closer look at the file.",
  ui_story_5065_50651505_6_dialog_content = "M-Me...? But why?",
  ui_story_5065_50651505_7_dialog_content = "Just open it and see!",
  ui_story_5065_50651505_8_dialog_content = "\"The Pyrrhus family, in conjunction with the Gautier family, made use of augmented Eclipsites to stage a violent rebellion...\"",
  ui_story_5065_50651505_9_dialog_content = "\"Every member of their respective families has been sentenced to death. In the event of further resistance, they shall be executed on the spot?!\"",
  ui_story_5065_50651505_10_dialog_content = "There must be some mistake, Lady Irridon!!",
  ui_story_5065_50651505_11_dialog_content = "Pam, don't you think... That you've seen a verdict like this before?",
  ui_story_5065_50651505_12_dialog_content = "H-Have I? It does feel as though I've seen this before, but where? Wait... You're trying to plant that idea in my mind, aren't you?",
  ui_story_5065_50651505_13_dialog_content = "You never actually lost this file! You wanted me to find it and read it, didn't you?",
  ui_story_5065_50651505_14_dialog_content = "Please stop trying to avoid it, Pam. Everything should be perfectly clear in your mind now, shouldn't it?",
  ui_story_5065_50651505_15_dialog_content = "Lady Irridon, I fear neither hardship nor humiliation...",
  ui_story_5065_50651505_16_dialog_content = "But I will not allow you to make a mockery of my family!",
  ui_story_5065_50651505_17_dialog_content = "Pam...",
  ui_story_5065_50651505_18_dialog_content = "Is there really no way to make her accept reality?",
  ui_story_5065_50651505_19_dialog_content = "I understand her all too well. Losing herself in these hopeful days of her life must bring her so much comfort and happiness.",
  ui_story_5065_50651505_20_dialog_content = "But by the God of Light, I swear that I'll never give up on her.",
  ui_story_5065_50651505_21_dialog_content = "If once isn't enough, then I'll just keep trying again and again. No matter how many times it takes...",
  ui_story_5065_50651505_22_dialog_content = "We'll succeed someday.",
  ui_story_5065_50651505_23_dialog_content = "Even if that means... Becoming enemies once again.",
  ui_story_5065_50651601_1_dialog_content = "Pam!",
  ui_story_5065_50651601_2_dialog_content = "Knight Commander... I'm so sorry!",
  ui_story_5065_50651601_3_dialog_content = "Why are you saying sorry?",
  ui_story_5065_50651601_4_dialog_content = "During my last assignment, I... I was unable to stop the suspect from taking his own life, and failed to discern his reasons for hiding Eclipsites in his home.",
  ui_story_5065_50651601_5_dialog_content = "Finding the culprit is already impressive. Leave the rest to the Hall of Justice.",
  ui_story_5065_50651601_6_dialog_content = "But right now, there's an even more urgent task for you.",
  ui_story_5065_50651601_7_dialog_content = "Based on our investigation, your mentor is implicated in treason. We have solid evidence and need to arrest her right away!",
  ui_story_5065_50651601_8_dialog_content = "However, your mentor is one of the most skilled members of the Investigation Division. It's risky to move without a solid plan.",
  ui_story_5065_50651601_9_dialog_content = "And you, as her assigned trainee, have a valid reason to get close to her...",
  ui_story_5065_50651601_10_dialog_content = "You want me to... Apprehend my instructor?",
  ui_story_5065_50651601_11_dialog_content = "This mission is undoubtedly challenging, But if you don't do it, you might end up looking like an accomplice...",
  ui_story_5065_50651601_12_dialog_content = "Were you truly able to find enough evidence to incriminate her? Has this arrest warrant... Been approved by the City Lord?",
  ui_story_5065_50651601_13_dialog_content = "Of course, I can verify everything you mentioned one by one.",
  ui_story_5065_50651601_14_dialog_content = "But first, you need to tell me, are you in or out on this mission?",
  ui_story_5065_50651601_15_dialog_content = "White Night up high! If my instructor is truly guilty of such heinous crimes...",
  ui_story_5065_50651601_16_dialog_content = "Then I have an obligation to arrest her!",
  ui_story_5065_50651602_1_dialog_content = "Pam, what's the matter? You don't usually look so troubled.",
  ui_story_5065_50651602_2_dialog_content = "... How could you do something like that?",
  ui_story_5065_50651602_3_dialog_content = "Huh?",
  ui_story_5065_50651602_4_dialog_content = "I'm grateful for the guidance you've offered me these last few days, but...",
  ui_story_5065_50651602_5_dialog_content = "Please forgive me! I have no choice but to repay you this way!",
  ui_story_5065_50651602_6_dialog_content = "Hold up! HOLD UP!",
  ui_story_5065_50651602_7_dialog_content = "Geez, a few gentle moves would have been enough. Why go all out?",
  ui_story_5065_50651602_8_dialog_content = "Even if I can save lives, you can't be so reckless.",
  ui_story_5065_50651602_9_dialog_content = "Sorry, I wanted to use this chance to test Pam's combat skills.",
  ui_story_5065_50651602_10_dialog_content = "Congratulations, you've passed the assessment of the current stage!",
  ui_story_5065_50651602_11_dialog_content = "Assessment? So... You were never plotting treason? But what about that arrest warrant and all of that evidence?",
  ui_story_5065_50651602_12_dialog_content = "Those were all fake, you know. Your mentor will teach you how to tell the real arrest warrants in the future!",
  ui_story_5065_50651602_13_dialog_content = "Ahem, but it wasn't our intention to deceive you, you know.",
  ui_story_5065_50651602_14_dialog_content = "The Lumopolis Temple mandated this format of assessment to see if you'd let emotions get in the way...",
  ui_story_5065_50651602_15_dialog_content = "Your ability to set aside personal emotions in the face of important decisions and hold your ground is precisely the quality the Lumopolis Temple's staff needs.",
  ui_story_5065_50651602_16_dialog_content = "Passing this assessment means you're one step closer to working in the Lumopolis Temple.",
  ui_story_5065_50651602_17_dialog_content = "Oh, thank the Light! I'm so relieved that you're not actually a traitor!",
  ui_story_5065_50651602_18_dialog_content = "But...",
  ui_story_5065_50651602_19_dialog_content = "What should I do if there's something wrong with my orders, or a judgment or arrest warrant for that matter?",
  ui_story_5065_50651602_20_dialog_content = "Sh-Should I still carry them out without question like this?",
  ui_story_5065_50651602_21_dialog_content = "The Lumopolis Temple's decisions represent the will of the God of Light. There are many levels of oversight before orders are issued.",
  ui_story_5065_50651602_22_dialog_content = "I-Is that so...",
  ui_story_5065_50651602_23_dialog_content = "Rest assured, the things you're worried about won't happen.",
  ui_story_5065_50651602_24_dialog_content = "Instead of worrying about all these what-ifs, you might as well ask your mentor more about your future career.",
  ui_story_5065_50651602_25_dialog_content = "... Understood!",
  ui_story_5065_50651602_26_dialog_content = "If I can truly become a scholar in the future, I will devote my entire life to serving the God of Light!",
  ui_story_5065_50651602_27_dialog_content = "Through my actions, I will bring the light to every household in Lumopolis and protect our beautiful home!",
  ui_story_5065_50651602_28_dialog_content = "Great, I can't wait to see the day when you become an official nun.",
  ui_story_5065_50651602_29_dialog_content = "But in the upcoming apprenticeship period, you will face many challenges, so you must stay sharp.",
  ui_story_5065_50651602_30_dialog_content = "Thank you for reminding me! I promise I'll work even harder to complete every trial set before me!",
  ui_story_5065_50651701_1_dialog_content = "Am I imagining things? Why does it feel like I'm constantly running into the same people and performing the same tasks...",
  ui_story_5065_50651701_2_dialog_content = "I feel so dizzy, and carrying out my assignments is becoming even more exhausting...",
  ui_story_5065_50651701_3_dialog_content = "How long have I been an initiate now? How much longer until I'm done?",
  ui_story_5065_50651701_4_dialog_content = "Why haven't I been promoted yet? Is it... Is it because I'm still not skilled enough to become a true nun?",
  ui_story_5065_50651701_5_dialog_content = "Or could this truly be...",
  ui_story_5065_50651701_6_dialog_content = "A dream?",
  ui_story_5065_50651701_7_dialog_content = "Lady Irridon?!",
  ui_story_5065_50651701_8_dialog_content = "Be honest, you realized the strangeness of this world a long time ago, didn't you?",
  ui_story_5065_50651701_9_dialog_content = "But you were unwilling to face the truth all this time. Isn't that so?",
  ui_story_5065_50651701_10_dialog_content = "N-No... I just wanted to work hard and earn my instructor's approval to become a nun of the Lumopolis Temple. I just...",
  ui_story_5065_50651701_11_dialog_content = "I just wanted to spare my family from even more pain!",
  ui_story_5065_50651701_12_dialog_content = "\"Even more pain\"?",
  ui_story_5065_50651701_13_dialog_content = "Ah, wh-what am I saying...? My family should be safe and sound in the Lumopolis Courtyard right now...",
  ui_story_5065_50651701_14_dialog_content = "But why does it feel like I haven't seen them in ages...?",
  ui_story_5065_50651701_15_dialog_content = "Why do I keep seeing images of them being arrested in my mind...?",
  ui_story_5065_50651701_16_dialog_content = "Those images must be the real nightmares here, right Lady Irridon?",
  ui_story_5065_50651701_17_dialog_content = "It's time to face reality, Pam.",
  ui_story_5065_50651701_18_dialog_content = "... Is this world truly nothing more than an illusion?",
  ui_story_5065_50651701_19_dialog_content = "But my dream is so close at hand! Just a little more, and I can finally become a true nun!",
  ui_story_5065_50651701_20_dialog_content = "If I wake up right now... Will all of this disappear?",
  ui_story_5065_50651701_21_dialog_content = "I'm so sorry, Pam...",
  ui_story_5065_50651701_22_dialog_content = "... Was that file you showed me also real?",
  ui_story_5065_50651701_23_dialog_content = "In other words, if I wake up from this dream, my family will no longer be with me...",
  ui_story_5065_50651701_24_dialog_content = "If that's the case, then why bother waking up? I could never survive all on my own.",
  ui_story_5065_50651701_25_dialog_content = "No, Pam. You're so much stronger than you know.",
  ui_story_5065_50651701_26_dialog_content = "Outside of this dream world, you are stronger, more confident, and fully aware of who you truly are.",
  ui_story_5065_50651701_27_dialog_content = "You will survive, and the life you'll lead is far more wonderful than you can imagine.",
  ui_story_5065_50651701_28_dialog_content = "Th-Then are we still friends in the real world?",
  ui_story_5065_50651701_29_dialog_content = "... We live in two different worlds out there, and the space between them is even greater than the space between this dream and reality.",
  ui_story_5065_50651701_30_dialog_content = "But I've always admired the Pam who lives on her own terms, even in a separate world.",
  ui_story_5065_50651701_31_dialog_content = "She dares to love and hate, and is much stronger than someone rooted in a place like myself.",
  ui_story_5065_50651701_32_dialog_content = "If those tragedies hadn't happened in the past, I'm certain we could have been good friends.",
  ui_story_5065_50651701_33_dialog_content = "But we are good friends!",
  ui_story_5065_50651701_34_dialog_content = "I-I'm starting to remember things. They're still so distant, but they're real.",
  ui_story_5065_50651701_35_dialog_content = "In those memories, we agreed to be friends. That's why you've been trying so hard to wake me up from this dream, isn't it?",
  ui_story_5065_50651701_36_dialog_content = "Even if this entire world is a lie, our friendship... is all too real!",
  ui_story_5065_50651701_37_dialog_content = "...",
  ui_story_5065_50651701_38_dialog_content = "That's right. I'll never forget that you were my very first friend.",
  ui_story_5065_50651701_39_dialog_content = "It's time to wake up!",
  ui_story_5065_50651701_40_dialog_content = "Did that magnifying glass just talk? And why does its voice sound so familiar...?",
  ui_story_5065_50651701_41_dialog_content = "When you wake up, you'll remember PlayerName.",
  ui_story_5065_50651701_42_dialog_content = "Although, it's possible that you met him well before I did.",
  ui_story_5065_50651701_43_dialog_content = "Are we going to wake up soon?",
  ui_story_5065_50651701_44_dialog_content = "Yes. My body... It's getting lighter and lighter... I'm starting to feel somewhat lonely too...",
  ui_story_5065_50651701_45_dialog_content = "Take my hand, Lady Irridon! That way you won't feel lonely anymore!",
  ui_story_5065_50651701_46_dialog_content = "...",
  ui_story_5065_50651701_47_dialog_content = "Thank you, my friend.",
  ui_story_5065_50651701_48_dialog_content = "We'll see each other again!"
}
return config
